<template>
	<div
		class="contacts-list__item-wrapper"
		:draggable="isDraggable"
		@dragstart="startDrag($event, source)"
		@click.shift.exact.prevent="onSelectMultipleRange"
		@keydown="onListKeydown">
		<ListItem
			:id="id"
			:key="source.key"
			class="list-item-style envelope"
			:name="source.displayName"
			:to="isStatic ? undefined : contactRoute(source.key)">
			<!-- @slot Icon slot -->

			<template #icon>
				<div
					class="contacts-list__item-icon"
					:role="isStatic ? undefined : 'checkbox'"
					:tabindex="isStatic ? undefined : 0"
					:aria-checked="isStatic ? undefined : source.isMultiSelected"
					:aria-label="isStatic ? undefined : selectAriaLabel"
					@click.exact.prevent="onSelectMultiple"
					@keydown.space.exact.prevent="onSelectMultiple"
					@keydown.enter.exact.prevent="onSelectMultiple"
					@keydown.shift.space.exact.prevent="onSelectMultipleRange"
					@mouseenter="hoverAvatar(true)"
					@mouseleave="hoverAvatar(false)">
					<NcAvatar
						v-if="((!source.isMultiSelected && !hoveringAvatar) || isStatic) && source.addressbook.id === 'z-server-generated--system'"
						:user="source.uid"
						:hide-status="true"
						:size="40" />
					<NcAvatar
						v-if="((!source.isMultiSelected && !hoveringAvatar) || isStatic) && source.addressbook.id !== 'z-server-generated--system'"
						:display-name="source.displayName"
						:url="avatarUrl"
						:size="40" />
					<CheckIcon
						v-if="(source.isMultiSelected || hoveringAvatar) && !isStatic"
						:size="28"
						:class="{ 'contacts-list__item-avatar-selected': source.isMultiSelected, 'contacts-list__item-avatar-hovered': !source.isMultiSelected }" />
					<div
						class="favorite-star"
						:class="{ favorite: isFavorite }"
						@click.stop="toggleFavorite">
						<StarIcon
							v-if="isFavorite"
							:size="16"
							class="favorite-icon" />
						<StarOutlineIcon
							v-else
							:size="16"
							class="favorite-icon" />
					</div>
				</div>
			</template>
			<template #subname>
				<div class="envelope__subtitle">
					<span class="envelope__subtitle__subject">
						{{ subtitle }}
					</span>
				</div>
				<div v-if="showAddressbook" class="envelope__subtitle">
					<span class="envelope__subtitle__addressbook">
						{{ t('contacts', 'from {addressbook}', { addressbook: source.addressbook.displayName }) }}
					</span>
				</div>
			</template>
			<template #actions>
				<NcActionButton
					v-if="!isStatic"
					@click="toggleFavorite">
					<template #icon>
						<StarIcon
							v-if="isFavorite"
							:size="20"
							class="favorite-icon" />
						<StarOutlineIcon
							v-else
							:size="20" />
					</template>
					{{ isFavorite ? t('contacts', 'Remove from favorites') : t('contacts', 'Add to favorites') }}
				</NcActionButton>
			</template>
		</ListItem>
	</div>
</template>

<script>
import { showError } from '@nextcloud/dialogs'
import {
	NcListItem as ListItem,
	NcActionButton,
	NcAvatar,
} from '@nextcloud/vue'
import CheckIcon from 'vue-material-design-icons/Check.vue'
import StarIcon from 'vue-material-design-icons/Star.vue'
import StarOutlineIcon from 'vue-material-design-icons/StarOutline.vue'
import RouterMixin from '../../mixins/RouterMixin.js'
import logger from '../../services/logger.js'

export default {
	name: 'ContactsListItem',

	components: {
		ListItem,
		NcAvatar,
		CheckIcon,
		NcActionButton,
		StarIcon,
		StarOutlineIcon,
	},

	mixins: [
		RouterMixin,
	],

	props: {
		index: {
			type: Number,
			required: true,
		},

		source: {
			type: Object,
			required: true,
		},

		reloadBus: {
			type: Object,
			required: true,
		},

		onSelectMultipleFromParent: {
			type: Function,
			default: () => {},
		},

		onNavigateFromParent: {
			type: Function,
			default: () => {},
		},

		isStatic: {
			type: Boolean,
			default: false,
			required: false,
		},

		showAddressbook: {
			type: Boolean,
			default: false,
			required: false,
		},
	},

	data() {
		return {
			avatarUrl: undefined,
			hoveringAvatar: false,
		}
	},

	computed: {
		isFavorite() {
			return this.source.favorite
		},

		subtitle() {
			if (this.source.org) {
				return this.source.org
			} else if (this.source.email) {
				return this.source.email
			} else {
				const tel = this.getTel
				if (tel) {
					return tel
				}
			}

			return ''
		},

		// contact is not draggable when it has not been saved on server as it can't be added to groups/circles before
		isDraggable() {
			return !!this.source.dav && this.source.addressbook.id !== 'z-server-generated--system' && !this.isStatic
		},

		// usable and valid html id for scrollTo
		id() {
			return this.source.key.slice(0, -2)
		},

		getTel() {
			return this.source.properties.find((property) => property.name === 'tel')?.getFirstValue()
		},

		selectAriaLabel() {
			return this.source.isMultiSelected
				? t('contacts', 'Unselect {name}', { name: this.source.displayName })
				: t('contacts', 'Select {name}', { name: this.source.displayName })
		},
	},

	created() {
		if (!this.isStatic) {
			this.reloadBus.on('reload-avatar', this.reloadAvatarUrl)
			this.reloadBus.on('delete-avatar', this.deleteAvatar)
		}
	},

	unmounted() {
		if (!this.isStatic) {
			this.reloadBus.off('reload-avatar', this.reloadAvatarUrl)
			this.reloadBus.off('delete-avatar', this.deleteAvatar)
		}
	},

	async mounted() {
		await this.loadAvatarUrl()
	},

	methods: {
		async toggleFavorite() {
			const contact = this.$store.getters.getContact(this.source.key)
			if (!contact) {
				this.logger.error('Could not find contact in store', this.source.key)
				showError(t('contacts', 'Could not update favorite status'))
				return
			}
			if (!contact.dav) {
				this.logger.error('Missing DAV object for contact', { contactKey: contact.key })
				showError(t('contacts', 'Could not update favorite status'))
				return
			}
			try {
				await this.$store.dispatch('toggleFavorite', contact)
			} catch (error) {
				logger.error('Could not toggle favorite state', error)
				showError(t('contacts', 'Could not update favorite status'))
			}
		},

		startDrag(evt, item) {
			evt.dataTransfer.dropEffect = 'move'
			evt.dataTransfer.effectAllowed = 'move'
			evt.dataTransfer.setData('item', JSON.stringify({
				addressbookId: item.addressbook.id,
				displayName: item.displayName,
				groups: item.groups,
				url: item.url,
				uid: item.uid,
			}))
		},

		/**
		 * Is called on save in ContactDetails to reload Avatar,
		 * url does not change, so trigger on source change don't work
		 *
		 * @param {string} key from contact
		 */
		reloadAvatarUrl(key) {
			if (key === this.source.key) {
				this.loadAvatarUrl()
			}
		},

		/**
		 * Is called on save in ContactDetails to delete Avatar,
		 * somehow the avatarUrl is not unavailable immediately, so we just set undefined
		 *
		 * @param {string} key from contact
		 */
		deleteAvatar(key) {
			if (key === this.source.key) {
				this.avatarUrl = undefined
			}
		},

		async loadAvatarUrl() {
			this.avatarUrl = undefined
			if (this.source.photo) {
				const photoUrl = await this.source.getPhotoUrl()
				if (!photoUrl) {
					logger.warn('contact has an invalid photo')
					// Invalid photo data
					return
				}
				this.avatarUrl = photoUrl
			} else if (this.source.hasPhoto && this.source.url) {
				this.avatarUrl = `${this.source.url}?photo`
			}
		},

		/**
		 * Select this contact within the list
		 */
		selectContact() {
			if (this.isStatic) {
				return
			}
			this.$router.push(this.contactRoute(this.source.key))
		},

		onSelectMultiple() {
			if (this.isStatic) {
				return
			}
			// This weirdness of passing a function as a prop is because the VirtualList extra-props prop object does not support listening to custom events (afaik)
			this.onSelectMultipleFromParent(this.source, this.index)
		},

		onSelectMultipleRange() {
			if (this.isStatic) {
				return
			}
			this.onSelectMultipleFromParent(this.source, this.index, true)
		},

		/**
		 * Handle arrow key navigation from this contact:
		 * - right moves focus into the contact details
		 * - up/down moves focus to the previous/next contact in the list
		 *
		 * @param {KeyboardEvent} event the keydown event
		 */
		onListKeydown(event) {
			if (this.isStatic) {
				return
			}

			if (event.key === 'ArrowRight') {
				event.preventDefault()
				this.selectContact()
				this.reloadBus.emit('focus-details')
			} else if (event.key === 'ArrowDown') {
				event.preventDefault()
				this.onNavigateFromParent(this.index, 'down')
			} else if (event.key === 'ArrowUp') {
				event.preventDefault()
				this.onNavigateFromParent(this.index, 'up')
			}
		},

		hoverAvatar(newState) {
			if (this.isStatic) {
				return
			}
			this.hoveringAvatar = newState
		},
	},
}
</script>

<style lang="scss" scoped>

