	.contacts-list__item-icon {
		height: 40px; // To prevent some unexpected spacing below the avatar
	}

	&__subtitle {
		display: flex;
		gap: var(--default-grid-baseline);

		&__subject {
			line-height: 130%;
			overflow: hidden;
			text-overflow: ellipsis;
		}

		&__addressbook {
			line-height: 130%;
			color: var(--color-text-maxcontrast);
		}
	}
}

:deep(.list-item) {
	list-style: none;
	padding-inline: calc(var(--default-grid-baseline) * 3);
	padding-block: calc(var(--default-grid-baseline) * 2);
}

</style>

<style lang="scss">
.contacts-list__item-wrapper {
	&[draggable='true'] .avatardiv * {
		cursor: move !important;
	}

	&[draggable='false'] .avatardiv * {
		cursor: not-allowed !important;
	}
}

.contacts-list__item-icon {
	cursor: pointer !important;
	position: relative;
}

.contacts-list__item-avatar {

	&-selected, &-hovered {
		border-radius: 32px;
		width: 40px;
		height: 40px;
		display: flex;
		align-items: center;
		justify-content: center;
	}

	&-selected {
		background-color: var(--color-primary-element);
		color: var(--color-primary-light);
	}

	&-hovered {
		color: var(--color-primary-hover);
		background-color: var(--color-primary-light-hover);
	}
}

.favorite-star {
	position: absolute;
	top: calc(var(--default-grid-baseline) * -1);
	inset-inline-end: calc(var(--default-grid-baseline) * -1);
	opacity: 0;
	cursor: pointer;
}

.contacts-list__item-icon:hover .favorite-star {
	opacity: 1;
}

.favorite-star.favorite {
	opacity: 1;
	color: var(--color-favorite)
}

.favorite-icon {
	color: var(--color-favorite);
}
</style>
