<template>
	<AppNavigation>
		<template #icon>
			<IconLoading v-if="loading" :size="20" />
		</template>

		<template #search>
			<header class="header">
				<slot />
			</header>
		</template>

		<!-- groups list -->
		<template #list>
			<!-- All contacts group -->
			<AppNavigationItem
				id="everyone"
				:name="GROUP_ALL_CONTACTS"
				:to="{
					name: 'group',
					params: { selectedGroup: GROUP_ALL_CONTACTS },
				}"
				:active="routeState === 'all'"
				@click="updateRouteState('all')">
				<template #icon>
					<IconContactFilled v-if="routeState === 'all'" :size="20" />
					<IconContact v-else :size="20" />
				</template>
				<template #counter>
					<NcCounterBubble
						v-if="sortedContacts.length"
						:count="sortedContacts.length" />
				</template>
			</AppNavigationItem>

			<!-- Organization chart -->
			<AppNavigationItem
				v-if="existChart"
				id="chart"
				:name="CHART_ALL_CONTACTS"
				:to="{
					name: 'chart',
					params: { selectedChart: GROUP_ALL_CONTACTS },
				}"
				:active="routeState === 'orgchart'"
				icon="icon-category-monitoring"
				@click="updateRouteState('orgchart')" />

			<!-- Not grouped group -->
			<AppNavigationItem
				v-if="ungroupedContacts.length > 0"
				id="notgrouped"
				:name="GROUP_NO_GROUP_CONTACTS"
				:to="{
					name: 'group',
					params: { selectedGroup: GROUP_NO_GROUP_CONTACTS },
				}"
				:active="routeState === 'notgrouped'"
				@click="updateRouteState('notgrouped')">
				<template #icon>
					<IconUserFilled v-if="routeState === 'notgrouped'" :size="20" />
					<IconUser v-else :size="20" />
				</template>
				<template #counter>
					<NcCounterBubble
						v-if="ungroupedContacts.length"
						:count="ungroupedContacts.length" />
				</template>
			</AppNavigationItem>

			<!-- Address books -->
			<AppNavigationCaption :name="t('contacts', 'Address books')">
				<template #actions>
					<NcActionButton @click="$refs.newAddressbook.openModal()">
						<template #icon>
							<IconAdd :size="20" />
						</template>
						{{ t('contacts', 'Add address book') }}
					</NcActionButton>
				</template>
			</AppNavigationCaption>
			<AppNavigationItem
				v-for="addressbook in enabledAddressbooks"
				:key="addressbook.id"
				:name="addressbook.displayName"
				:to="{
					name: ROUTE_ADDRESSBOOK,
					params: { selectedAddressbook: addressbook.id },
				}"
				:active="routeState === `${ROUTE_ADDRESSBOOK}:${addressbook.id}`"
				@click="updateRouteState(`${ROUTE_ADDRESSBOOK}:${addressbook.id}`)">
				<template #icon>
					<IconAddressBook :size="20" />
				</template>
				<template #counter>
					<NcCounterBubble
						v-if="addressbookContactCount(addressbook)"
						:count="addressbookContactCount(addressbook)" />
				</template>
			</AppNavigationItem>

			<!-- Recently contacted group -->
			<AppNavigationItem
				v-if="isContactsInteractionEnabled && recentlyContactedContacts && recentlyContactedContacts.contacts.length > 0"
				id="recentlycontacted"
				:name="t('contacts', 'Recently contacted')"
				:to="{
					name: 'group',
					params: { selectedGroup: GROUP_RECENTLY_CONTACTED },
				}"
				:active="routeState === 'recentlycontacted'"
				@click="updateRouteState('recentlycontacted')">
				<template #icon>
					<IconRecentlyContacted :size="20" />
				</template>
				<template #counter>
					<NcCounterBubble
						v-if="recentlyContactedContacts.contacts.length"
						:count="recentlyContactedContacts.contacts.length" />
				</template>
			</AppNavigationItem>

			<AppNavigationCaption
				id="newgroup"
				v-model:menu-open="isNewGroupMenuOpen"
				:force-menu="true"
				:name="t('contacts', 'Contact groups')"
				@click.prevent.stop="toggleNewGroupMenu">
				<template #actionsTriggerIcon>
					<IconAdd :size="20" />
				</template>
				<template #actions>
					<ActionText v-show="isNewGroupMenuOpen">
						<template #icon>
							<IconError v-if="createGroupError" :size="20" />
							<IconContact v-else-if="!createGroupError" :size="20" />
						</template>
						{{ createGroupError ? createGroupError : t('contacts', 'Create a new contact group') }}
					</ActionText>
					<ActionInput
						v-show="isNewGroupMenuOpen"
						icon=""
						:placeholder="t('contacts', 'Contact group name')"
						@submit.prevent.stop="createNewGroup" />
				</template>
			</AppNavigationCaption>

			<!-- Custom groups -->
			<GroupNavigationItem
				v-for="group in ellipsisGroupsMenu"
				:key="group.key"
				:route-state="routeState"
				:group="group"
				@update-route-state="updateRouteState" />
		</template>

		<!-- settings -->

		<template #footer>
			<div class="contacts-settings">
				<NcButton
					:aria-label="t('contacts', 'Open the contacts app settings')"
					variant="tertiary"
					:wide="true"
					@click="showContactsSettings">
					<template #icon>
						<Cog :size="20" />
					</template>
					{{ CONTACTS_SETTINGS }}
				</NcButton>
			</div>
		</template>
		<ContactsSettings v-model:open="showSettings" />
		<SettingsNewAddressbook ref="newAddressbook" hide-button />
	</AppNavigation>
</template>

<script>
import { showError } from '@nextcloud/dialogs'
import { emit } from '@nextcloud/event-bus'
import {
	NcActionInput as ActionInput,
	NcActionText as ActionText,
	NcAppNavigation as AppNavigation,
	NcAppNavigationCaption as AppNavigationCaption,
	NcAppNavigationItem as AppNavigationItem,
	NcLoadingIcon as IconLoading,
	NcButton,
	NcCounterBubble,
} from '@nextcloud/vue'
import { mapStores } from 'pinia'
import naturalCompare from 'string-natural-compare'
import IconUserFilled from 'vue-material-design-icons/Account.vue'
import IconContactFilled from 'vue-material-design-icons/AccountMultiple.vue'
import IconContact from 'vue-material-design-icons/AccountMultipleOutline.vue'
import IconUser from 'vue-material-design-icons/AccountOutline.vue'
import IconError from 'vue-material-design-icons/AlertCircleOutline.vue'
import IconAddressBook from 'vue-material-design-icons/BookAccountOutline.vue'
import Cog from 'vue-material-design-icons/CogOutline.vue'
import IconAdd from 'vue-material-design-icons/Plus.vue'
import IconRecentlyContacted from '../Icons/IconRecentlyContacted.vue'
import ContactsSettings from './ContactsSettings.vue'
import GroupNavigationItem from './GroupNavigationItem.vue'
import SettingsNewAddressbook from './Settings/SettingsNewAddressbook.vue'
import RouterMixin from '../../mixins/RouterMixin.js'
import { CHART_ALL_CONTACTS, CONTACTS_SETTINGS, ELLIPSIS_COUNT, GROUP_ALL_CONTACTS, GROUP_NO_GROUP_CONTACTS, GROUP_RECENTLY_CONTACTED, ROUTE_ADDRESSBOOK } from '../../models/constants.ts'
import isContactsInteractionEnabled from '../../services/isContactsInteractionEnabled.js'
import useUserGroupStore from '../../store/userGroup.ts'

export default {
	name: 'RootNavigation',

	components: {
		ActionInput,
		ActionText,
		AppNavigation,
		NcCounterBubble,
		AppNavigationItem,
		AppNavigationCaption,
		Cog,
		ContactsSettings,
		GroupNavigationItem,
		IconAddressBook,
		IconContact,
		IconContactFilled,
		IconUser,
		IconUserFilled,
		IconAdd,
		IconError,
		IconLoading,
		IconRecentlyContacted,
		NcButton,
		SettingsNewAddressbook,
	},

	mixins: [RouterMixin],

	props: {
		loading: {
			type: Boolean,
			default: false,
		},
	},

	data() {
		return {
			CONTACTS_SETTINGS,
			ELLIPSIS_COUNT,
			GROUP_ALL_CONTACTS,
			CHART_ALL_CONTACTS,
			GROUP_NO_GROUP_CONTACTS,
			GROUP_RECENTLY_CONTACTED,
			ROUTE_ADDRESSBOOK,

			// create group
			isNewGroupMenuOpen: false,
			createGroupError: null,

			isContactsInteractionEnabled,

			collapsedGroups: true,

			showSettings: false,

			routeState: 'all',
		}
	},

	computed: {
		// store variables
		addressbooks() {
			return this.$store.getters.getAddressbooks
		},

		enabledAddressbooks() {
			return this.addressbooks.filter((ab) => ab.enabled)
		},

		contacts() {
			const contacts = this.$store.getters.getContacts
			if (contacts.undefined) {
				contacts[this.selectedContact] = contacts.undefined
				delete contacts.undefined
			}

			return this.$store.getters.getContacts
		},

		groups() {
			return this.$store.getters.getGroups
		},

		sortedContacts() {
			return this.$store.getters.getSortedContacts
		},

		userGroups() {
			return this.userGroupStore.userGroupList
		},

		// list all the contacts that doesn't have a group
		ungroupedContacts() {
			return this.sortedContacts.filter((contact) => this.contacts[contact.key]?.groups && this.contacts[contact.key]?.groups?.length === 0)
		},

		// check if any contact has manager, if not then is no need for organization chart menu
		existChart() {
			return !!Object.keys(this.contacts).filter((key) => this.contacts[key].managersName).length
		},

		// generate groups menu from the groups store
		groupsMenu() {
			const menu = this.groups.map((group) => {
				return {
					...group,
					id: group.name.replace(' ', '_'),
					key: group.name.replace(' ', '_'),
					router: {
						name: 'group',
						params: { selectedGroup: group.name },
					},
					toString: () => group.name,
				}
			})
			menu.sort((a, b) => naturalCompare(a.toString(), b.toString(), { caseInsensitive: true }))

			// Find the Recently Contacted group, delete it from array
			const recentlyIndex = menu.findIndex((group) => group.name === GROUP_RECENTLY_CONTACTED)
			if (recentlyIndex >= 0) {
				menu.splice(recentlyIndex, 1)
			}

			return menu
		},

		ellipsisGroupsMenu() {
			if (this.collapsedGroups) {
				return this.groupsMenu.slice(0, ELLIPSIS_COUNT)
			}
			return this.groupsMenu
		},

		// Recently contacted data
		recentlyContactedContacts() {
			return this.groups.find((group) => group.name === GROUP_RECENTLY_CONTACTED)
		},

		// Titles for the ellipsis toggle buttons
		collapseGroupsTitle() {
			return this.collapsedGroups
				? t('contacts', 'Show all groups')
				: t('contacts', 'Collapse groups')
		},

		...mapStores(useUserGroupStore),
	},

	methods: {
		addressbookContactCount(addressbook) {
			// contact groups are stored as contacts too, but never listed as such
			return Object.values(addressbook.contacts || {}).filter((contact) => contact.kind !== 'group').length
		},

		toggleNewGroupMenu() {
			this.isNewGroupMenuOpen = !this.isNewGroupMenuOpen
		},

		createNewGroup(e) {
			const input = e.target.querySelector('input[type=text]')
			const groupName = input.value.trim()
			if (groupName.length === 0) {
				showError(t('contacts', 'Group name cannot be empty'))
				return
			}
			this.logger.debug('Creating new group', { groupName })

			// Check if already exists
			if (this.groups.find((group) => group.name === groupName)) {
				this.createGroupError = t('contacts', 'This group already exists')
				emit('contacts:group:append', this.groups.find((group) => group.name === groupName).name)
				return
			}

			this.createGroupError = null
			this.logger.debug('Created new local group', { groupName })

			try {
				this.$store.dispatch('addGroup', groupName)
				this.isNewGroupMenuOpen = false
				emit('contacts:group:append', groupName)
			} catch (error) {
				showError(t('contacts', 'An error occurred while creating the group'))
			}
		},

		// Ellipsis item toggles
		onToggleGroups() {
			this.collapsedGroups = !this.collapsedGroups
		},

		/**
		 * Shows the contacts settings
		 */
		showContactsSettings() {
			this.showSettings = true
		},

		updateRouteState(state) {
			this.routeState = state
		},
	},
}
</script>

